import React, { useState } from 'react';

type Filters = {
    brand: string;
    model: string;
    year: string;
    features: string[];
};

const featuresList = ['Навигация', 'Климатик', 'Кожен салон', 'Парктроник'];

const SearchCar: React.FC = () => {
    const [filters, setFilters] = useState<Filters>({
        brand: '',
        model: '',
        year: '',
        features: [],
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({
            ...prev,
            [name]: value,
        }));
    };

    const handleFeaturesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { value, checked } = e.target;
        setFilters(prev => ({
            ...prev,
            features: checked
                ? [...prev.features, value]
                : prev.features.filter(f => f !== value),
        }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        console.log('Фильтры для поиска:', filters);
        // Здесь можно отправить фильтры на сервер
    };

    return (
        <div className="max-w-4xl mx-auto bg-white p-10 rounded-2xl shadow-lg mt-10">
            <h1 className="text-4xl font-bold text-center text-gray-800 mb-8">Find your car!</h1>

            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <label className="block text-gray-700 font-medium mb-2">Марка</label>
                        <select
                            name="brand"
                            value={filters.brand}
                            onChange={handleChange}
                            className="w-full border border-gray-300 rounded-xl p-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        >
                            <option value="">-- Избери --</option>
                            <option value="Toyota">Toyota</option>
                            <option value="BMW">BMW</option>
                            <option value="Audi">Audi</option>
                        </select>
                    </div>

                    <div>
                        <label className="block text-gray-700 font-medium mb-2">Модел</label>
                        <input
                            type="text"
                            name="model"
                            value={filters.model}
                            onChange={handleChange}
                            placeholder="напр. Corolla"
                            className="w-full border border-gray-300 rounded-xl p-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                    </div>

                    <div>
                        <label className="block text-gray-700 font-medium mb-2">Година</label>
                        <input
                            type="number"
                            name="year"
                            value={filters.year}
                            onChange={handleChange}
                            placeholder="напр. 2020"
                            className="w-full border border-gray-300 rounded-xl p-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                    </div>
                </div>

                <div>
                    <label className="block text-gray-700 font-medium mb-2">Екстри</label>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {featuresList.map(feature => (
                            <label key={feature} className="flex items-center gap-2 text-gray-600">
                                <input
                                    type="checkbox"
                                    value={feature}
                                    checked={filters.features.includes(feature)}
                                    onChange={handleFeaturesChange}
                                    className="accent-blue-600"
                                />
                                {feature}
                            </label>
                        ))}
                    </div>
                </div>

                <div className="text-center pt-4">
                    <button
                        type="submit"
                        className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-8 rounded-full shadow-md transition"
                    >
                        Търси
                    </button>
                </div>
            </form>
        </div>
    );
};

export default SearchCar;
